        margin: 0 0 1rem;
        color: var(--color-primary);
        font-size: 0.875rem;
        font-weight: 800;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1 {
        max-width: 12ch;
        margin: 0;
        font-size: clamp(2.5rem, 6vw, 5rem);
        line-height: 0.95;
        letter-spacing: -0.06em;
      }

      .intro {
        max-width: 35rem;
        margin: 1.5rem 0 0;
        color: var(--color-muted);
        font-size: 1.125rem;
      }

      .contact-card {
        border: 1px solid #d8e0eb;
        border-radius: 1.5rem;
        background: var(--color-surface);
        box-shadow: var(--shadow-card);
        padding: clamp(1.25rem, 4vw, 2rem);
      }

      .form-title {
        margin: 0 0 0.5rem;
        font-size: 1.5rem;
        line-height: 1.2;
      }

      .form-note {
        margin: 0 0 1.5rem;
        color: var(--color-muted);
      }

      .form-field {
        margin-block: 1rem;
      }

      label {
        display: flex;
        justify-content: space-between;
        gap: 1rem;
        margin-bottom: 0.45rem;
        color: var(--color-text);
        font-size: 0.95rem;
        font-weight: 700;
      }

      .required {
        color: var(--color-muted);
        font-size: 0.85rem;
        font-weight: 700;
      }

      .optional {
        color: var(--color-muted);
        font-size: 0.85rem;
        font-weight: 600;
      }

      input {
        width: 100%;
        min-height: 3rem;
        border: 1px solid var(--color-border);
        border-radius: 0.875rem;
        background: #ffffff;
        color: var(--color-text);
        padding: 0.8rem 0.95rem;
        font: inherit;
      }

      input:hover {
        border-color: #7e8da1;
      }

      input:focus {
        border-color: var(--color-primary);
        outline: 3px solid transparent;
        box-shadow: 0 0 0 3px #aec4ff;
      }

      .helper-text {
        margin: 0.45rem 0 0;
        color: var(--color-muted);
        font-size: 0.9rem;
      }

      .submit-button {
        width: 100%;
        min-height: 3.2rem;
        margin-top: 1.25rem;
        border: 1px solid var(--color-primary);
        border-radius: 999px;
        background: var(--color-primary);
        color: #ffffff;
        cursor: pointer;
        font: inherit;
        font-weight: 800;
        letter-spacing: 0.01em;
      }

      .submit-button:hover {
        background: var(--color-primary-hover);
        border-color: var(--color-primary-hover);
      }

      .submit-button:focus {
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px #aec4ff;
      }

      @media (max-width: 48rem) {
        .page-shell {
          padding: 1rem;
        }

        .hero {
          grid-template-columns: 1fr;
          gap: 2rem;
          align-items: start;
          min-height: auto;
          padding-block: 3rem;
        }

        h1 {
          max-width: 11ch;
        }
