          border-color: ButtonBorder;
        }

        .submit-button {
          background: ButtonFace;
          color: ButtonText;
        }

        input:focus,
        .submit-button:focus {
          outline: 3px solid Highlight;
          box-shadow: none;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="root"></div>

    <script>
      const fields = [
        {
          id: "full-name",
          name: "fullName",
          label: "Full name",
          autocomplete: "name",
          type: "text",
          required: true
        },
        {
          id: "email-address",
          name: "email",
          label: "Email address",
          autocomplete: "email",
          type: "email",
          required: true
        },
        {
          id: "phone-number",
          name: "phone",
          label: "Phone number",
          autocomplete: "tel",
          type: "tel",
          required: false,
          helperId: "phone-format-help",
          helperText: "Use digits, spaces, dashes, or parentheses, such as (555) 123-4567."
        }
      ];

      function Field({ id, name, label, autocomplete, type, required, helperId, helperText }) {
        const requirementText = required
          ? '<span class="required" aria-hidden="true">Required</span>'
          : '<span class="optional">Optional</span>';
        const helperMarkup = helperText
