          : "";
        const describedBy = helperId ? ` aria-describedby="${helperId}"` : "";
        const requiredAttribute = required ? " required" : "";

        return `
          <div class="form-field">
            <label for="${id}">
              <span>${label}</span>
              ${requirementText}
            </label>
            <input
              id="${id}"
              name="${name}"
              type="${type}"
              autocomplete="${autocomplete}"
              ${describedBy}
              ${requiredAttribute}
            >
            ${helperMarkup}
          </div>
        `;
      }

      function ContactForm() {
        return `
          <section class="contact-card" aria-labelledby="contact-form-heading">
            <h2 class="form-title" id="contact-form-heading">Contact support</h2>
            <p class="form-note">Tell us how to reach you and our support team will follow up.</p>
            <form action="#" method="post" novalidate>
              ${fields.map(Field).join("")}
              <button class="submit-button" type="submit">Submit request</button>
            </form>
          </section>
        `;
      }

      function App() {
        return `
          <main class="page-shell" id="main-content">
            <div class="hero">
              <section aria-labelledby="page-title">
                <p class="eyebrow">Support</p>
                <h1 id="page-title">How can we help?</h1>
                <p class="intro">
                  Send a few details to our team and we will route your request to the
                  right specialist.
                </p>
              </section>
              ${ContactForm()}
            </div>
          </main>
        `;
      }

      document.querySelector("#root").innerHTML = App();
    </script>
